{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2176-05-03 11:30:00",
      "speaker": "Doctor",
      "text": "Good morning. I’m Dr. Lee, one of the neurology team. You’re here for your 18th cycle of high-dose methotrexate for your CNS lymphoma, correct?"
    },
    {
      "turn_number": 2,
      "time": "2176-05-03 11:31:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. I just got back from vacation with my husband, so I’m feeling pretty good today."
    },
    {
      "turn_number": 3,
      "time": "2176-05-03 11:32:00",
      "speaker": "Doctor",
      "text": "That’s great to hear. We’ll make sure this cycle goes smoothly. We’ll start with some baseline labs and then give the methotrexate infusion this afternoon."
    },
    {
      "turn_number": 4,
      "time": "2176-05-03 11:33:00",
      "speaker": "Patient",
      "text": "Okay. Do I need to do anything special before the infusion?"
    },
    {
      "turn_number": 5,
      "time": "2176-05-03 11:34:00",
      "speaker": "Doctor",
      "text": "We’ll start IV fluids to help protect your kidneys and give you some anti-nausea meds beforehand. We also give sodium bicarbonate to help clear the methotrexate faster."
    },
    {
      "turn_number": 6,
      "time": "2176-05-03 11:35:00",
      "speaker": "Patient",
      "text": "And the leucovorin? When does that start?"
    },
    {
      "turn_number": 7,
      "time": "2176-05-03 11:36:00",
      "speaker": "Doctor",
      "text": "Exactly 24 hours after the methotrexate starts. It helps protect your healthy cells. We’ll monitor your levels daily until they drop low enough."
    },
    {
      "turn_number": 8,
      "time": "2176-05-03 11:37:00",
      "speaker": "Patient",
      "text": "Got it. Last time my liver enzymes went up a little. Is that expected?"
    },
    {
      "turn_number": 9,
      "time": "2176-05-03 11:38:00",
      "speaker": "Doctor",
      "text": "Yes, mild elevation is common and usually temporary. We’ll keep an eye on it, but it’s not a concern unless it gets much higher."
    },
    {
      "turn_number": 10,
      "time": "2176-05-03 11:39:00",
      "speaker": "Patient",
      "text": "Okay, good. My foot pain has been bothering me more lately. Could that be from the chemo?"
    },
    {
      "turn_number": 11,
      "time": "2176-05-03 11:40:00",
      "speaker": "Doctor",
      "text": "It’s possible, but we’ve done MRIs and ultrasounds and haven’t found a clear cause. It may not be directly related. We’ll keep you on gabapentin and oxycodone as needed."
    },
    {
      "turn_number": 12,
      "time": "2176-05-03 11:41:00",
      "speaker": "Patient",
      "text": "I’ve been taking the gabapentin regularly. It helps a little, but not completely."
    },
    {
      "turn_number": 13,
      "time": "2176-05-03 11:42:00",
      "speaker": "Doctor",
      "text": "We’ll make sure your primary care doctor knows so they can look into it further. Maybe a pain specialist can help."
    },
    {
      "turn_number": 14,
      "time": "2176-05-03 12:15:00",
      "speaker": "Doctor",
      "text": "The infusion is starting now. It’ll take a few hours. You should feel fine—most people don’t have immediate side effects."
    },
    {
      "turn_number": 15,
      "time": "2176-05-03 12:16:00",
      "speaker": "Patient",
      "text": "Thanks. I brought a book, so I’ll just relax."
    },
    {
      "turn_number": 16,
      "time": "2176-05-03 14:30:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Halfway through the infusion. Any nausea or headache?"
    },
    {
      "turn_number": 17,
      "time": "2176-05-03 14:31:00",
      "speaker": "Patient",
      "text": "No, I feel okay. Just a little tired."
    },
    {
      "turn_number": 18,
      "time": "2176-05-03 16:00:00",
      "speaker": "Doctor",
      "text": "Infusion is complete. Great job. We’ll keep the IV fluids going and check your labs tomorrow morning."
    },
    {
      "turn_number": 19,
      "time": "2176-05-03 16:01:00",
      "speaker": "Patient",
      "text": "Should I expect to feel different tomorrow?"
    },
    {
      "turn_number": 20,
      "time": "2176-05-03 16:02:00",
      "speaker": "Doctor",
      "text": "Some people feel a bit fatigued or have mild nausea, but we’ll give you meds if needed. The key is staying hydrated."
    },
    {
      "turn_number": 21,
      "time": "2176-05-04 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are back. Your methotrexate level is 0.21, which is where we want it. Kidney and liver values are stable."
    },
    {
      "turn_number": 22,
      "time": "2176-05-04 08:01:00",
      "speaker": "Patient",
      "text": "That’s good. Does that mean I’m on track to go home soon?"
    },
    {
      "turn_number": 23,
      "time": "2176-05-04 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, once it drops below 0.2, you can go home. We’ll check again tomorrow morning."
    },
    {
      "turn_number": 24,
      "time": "2176-05-04 08:03:00",
      "speaker": "Patient",
      "text": "And the brain MRI I had yesterday—any results?"
    },
    {
      "turn_number": 25,
      "time": "2176-05-04 08:04:00",
      "speaker": "Doctor",
      "text": "I just got the report. No new lesions or signs of lymphoma recurrence. Everything looks stable."
    },
    {
      "turn_number": 26,
      "time": "2176-05-04 08:05:00",
      "speaker": "Patient",
      "text": "Oh, that’s such a relief. Thank you."
    },
    {
      "turn_number": 27,
      "time": "2176-05-04 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, very good news. We also saw some chronic sinus inflammation, but that’s not new and doesn’t need treatment."
    },
    {
      "turn_number": 28,
      "time": "2176-05-04 10:00:00",
      "speaker": "Patient",
      "text": "I forgot—why did we stop my aspirin again?"
    },
    {
      "turn_number": 29,
      "time": "2176-05-04 10:01:00",
      "speaker": "Doctor",
      "text": "Because aspirin can interfere with methotrexate clearance. We hold it during the cycle to protect your kidneys."
    },
    {
      "turn_number": 30,
      "time": "2176-05-04 10:02:00",
      "speaker": "Patient",
      "text": "Right, and I can restart it when I go home?"
    },
    {
      "turn_number": 31,
      "time": "2176-05-04 10:03:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll write that order. You’ve been on it for your history of DVT and PE, so it’s important to continue."
    },
    {
      "turn_number": 32,
      "time": "2176-05-04 10:04:00",
      "speaker": "Patient",
      "text": "I’m glad it’s just temporary. I worry about clots."
    },
    {
      "turn_number": 33,
      "time": "2176-05-04 10:05:00",
      "speaker": "Doctor",
      "text": "Understandable. But your risk is low now, especially with the aspirin back on."
    },
    {
      "turn_number": 34,
      "time": "2176-05-05 07:50:00",
      "speaker": "Doctor",
      "text": "Good morning. Your methotrexate level is now 0.07—excellent. That means you’re ready to go home today."
    },
    {
      "turn_number": 35,
      "time": "2176-05-05 07:51:00",
      "speaker": "Patient",
      "text": "That’s great! Do I need to take extra leucovorin or sodium bicarbonate at home?"
    },
    {
      "turn_number": 36,
      "time": "2176-05-05 07:52:00",
      "speaker": "Doctor",
      "text": "No, because your level is so low. Just continue your regular meds and stay hydrated."
    },
    {
      "turn_number": 37,
      "time": "2176-05-05 07:53:00",
      "speaker": "Patient",
      "text": "And my citalopram—I should keep taking that every day?"
    },
    {
      "turn_number": 38,
      "time": "2176-05-05 07:54:00",
      "speaker": "Doctor",
      "text": "Yes, absolutely. You’ve been doing well emotionally, and we want to keep it that way."
    },
    {
      "turn_number": 39,
      "time": "2176-05-05 07:55:00",
      "speaker": "Patient",
      "text": "I feel much better than I did a few cycles ago. I was really overwhelmed then."
    },
    {
      "turn_number": 40,
      "time": "2176-05-05 07:56:00",
      "speaker": "Doctor",
      "text": "It’s a lot to go through. But you’re handling it well now, and your mood is stable."
    },
    {
      "turn_number": 41,
      "time": "2176-05-05 07:57:00",
      "speaker": "Patient",
      "text": "What about the next steps with my oncologist?"
    },
    {
      "turn_number": 42,
      "time": "2176-05-05 07:58:00",
      "speaker": "Doctor",
      "text": "Dr. ___ plans to start you on Rituxan after this cycle. You’ll discuss that at your next clinic visit."
    },
    {
      "turn_number": 43,
      "time": "2176-05-05 07:59:00",
      "speaker": "Patient",
      "text": "Is that another chemo drug?"
    },
    {
      "turn_number": 44,
      "time": "2176-05-05 08:00:00",
      "speaker": "Doctor",
      "text": "It’s a targeted therapy—works with your immune system. It’s often used with methotrexate for lymphoma."
    },
    {
      "turn_number": 45,
      "time": "2176-05-05 08:01:00",
      "speaker": "Patient",
      "text": "Okay, I’ll ask about it then. And my foot pain—I should see my PCP about that?"
    },
    {
      "turn_number": 46,
      "time": "2176-05-05 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, please do. It’s not clearly related to chemo, so your doctor might refer you to a specialist."
    },
    {
      "turn_number": 47,
      "time": "2176-05-05 08:03:00",
      "speaker": "Patient",
      "text": "I’ll make an appointment. I just want to walk more without pain."
    },
    {
      "turn_number": 48,
      "time": "2176-05-05 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll include that in your discharge instructions. Otherwise, you’re doing very well."
    },
    {
      "turn_number": 49,
      "time": "2176-05-05 10:30:00",
      "speaker": "Doctor",
      "text": "Your discharge orders are in. You can go home in about an hour. Just sign the papers and get your prescriptions."
    },
    {
      "turn_number": 50,
      "time": "2176-05-05 10:31:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I really appreciate the care."
    },
    {
      "turn_number": 51,
      "time": "2176-05-05 10:32:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and see you at your next cycle."
    },
    {
      "turn_number": 52,
      "time": "2176-05-06 09:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave. How are you feeling this morning?"
    },
    {
      "turn_number": 53,
      "time": "2176-05-06 09:01:00",
      "speaker": "Patient",
      "text": "Good. No nausea or headaches. Ready to go home."
    },
    {
      "turn_number": 54,
      "time": "2176-05-06 09:02:00",
      "speaker": "Doctor",
      "text": "Vitals are stable. Your hemoglobin is a bit low, but that’s expected from chemo. No anemia symptoms?"
    },
    {
      "turn_number": 55,
      "time": "2176-05-06 09:03:00",
      "speaker": "Patient",
      "text": "Just a little tired sometimes, but nothing severe."
    },
    {
      "turn_number": 56,
      "time": "2176-05-06 09:04:00",
      "speaker": "Doctor",
      "text": "That’s common. Keep eating well and resting. We’ll monitor it next cycle."
    },
    {
      "turn_number": 57,
      "time": "2176-05-06 09:05:00",
      "speaker": "Patient",
      "text": "And my asthma has been fine. I’ve been using my inhalers as usual."
    },
    {
      "turn_number": 58,
      "time": "2176-05-06 09:06:00",
      "speaker": "Doctor",
      "text": "Good. No wheezing or shortness of breath?"
    },
    {
      "turn_number": 59,
      "time": "2176-05-06 09:07:00",
      "speaker": "Patient",
      "text": "No, all clear."
    },
    {
      "turn_number": 60,
      "time": "2176-05-06 09:08:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re cleared to go home. Take it easy for a few days."
    },
    {
      "turn_number": 61,
      "time": "2176-05-06 09:09:00",
      "speaker": "Patient",
      "text": "I will. Thanks again for everything."
    },
    {
      "turn_number": 62,
      "time": "2176-05-06 09:10:00",
      "speaker": "Doctor",
      "text": "You’re doing great. See you soon."
    },
    {
      "turn_number": 63,
      "time": "2176-05-06 12:00:00",
      "speaker": "Doctor",
      "text": "Just confirming—you’re leaving now, right?"
    },
    {
      "turn_number": 64,
      "time": "2176-05-06 12:01:00",
      "speaker": "Patient",
      "text": "Yes, the cab is here. I’m all set."
    },
    {
      "turn_number": 65,
      "time": "2176-05-06 12:02:00",
      "speaker": "Doctor",
      "text": "Safe travels. Call if you have any concerns."
    },
    {
      "turn_number": 66,
      "time": "2176-05-06 12:03:00",
      "speaker": "Patient",
      "text": "I will. Thank you!"
    },
    {
      "turn_number": 67,
      "time": "2176-05-06 12:04:00",
      "speaker": "Doctor",
      "text": "Take care."
    }
  ],
  "summary": {
    "admission_start": "2176-05-03 11:23:00",
    "admission_end": "2176-05-06 12:24:00",
    "summary_paragraph": "A 50-year-old woman with primary central nervous system lymphoma, ulcerative colitis, asthma, and a history of DVT/PE was admitted for her 18th cycle of high-dose methotrexate chemotherapy. She tolerated the treatment well with no significant side effects. Methotrexate levels declined appropriately, falling to 0.07 by discharge, with no renal toxicity. Liver enzymes showed mild, expected elevation. A brain MRI confirmed stable disease without lymphoma recurrence. Aspirin was held during admission to optimize methotrexate excretion and was restarted at discharge. She remained emotionally stable on citalopram with no depressive symptoms. Chronic right foot pain persisted and was managed with gabapentin and PRN oxycodone; she was advised to follow up with her primary care physician for further evaluation. She was discharged home in good condition with plans to start Rituxan in the upcoming cycle.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Other malignant lymphomas, unspecified site, extranodal and solid organ sites",
      "Ulcerative colitis, unspecified",
      "Personal history of venous thrombosis and embolism",
      "Asthma, unspecified type, unspecified",
      "Personal history of pulmonary embolism",
      "Depressive disorder, not elsewhere classified",
      "Antineoplastic chemotherapy induced anemia",
      "Antineoplastic and immunosuppressive drugs causing adverse effects in therapeutic use",
      "Nonspecific elevation of levels of transaminase or lactic acid dehydrogenase [LDH]"
    ]
  }
}
